/*
 * Every scan or bind site must resolve its element through `getApp(el, this)`. It's
 * the only thing keeping a parent app from binding a nested app's elements.
 *
 * A listener on `app.root` hears a nested app's events too, since they bubble. A new
 * root-level listener that acts on Rouse events must skip any event whose target
 * `getApp` doesn't resolve to its app, as the payload routers do, or it handles a
 * nested app's payload twice.
 *
 * Don't make `start()` automatic. There's no moment when registration is known to be
 * finished, and an interceptor registered after the first scan would miss requests
 * that scan fires, such as `data-rz-fetch="ready"`.
 */
import { BOUND_DIRECTIVES, STANDALONE_DIRECTIVES } from './directives';
import {
  appAt,
  attachApp,
  detachApp,
  registerBoundDirectives,
  teardownGlobalBindings,
} from './dom/binder';
import { on, type TriggerSource, triggerSources } from './dom/events';
import {
  addStandaloneSlug,
  flushMutations,
  mountSubtree,
  observeApp,
  releaseSubtree,
  unmountSubtree,
  unobserveApp,
} from './dom/observer';
import { placeContent } from './dom/placer';
import { runFetch } from './net/fetch-engine';
import type {
  BoundOn,
  DirectiveSlug,
  ErrorInterceptor,
  FetchRequest,
  InterceptorOptions,
  InterceptorPhase,
  ListenerOptions,
  PlaceOptions,
  RequestInterceptor,
  ResponseInterceptor,
  RouseFetch,
  ScopeSetup,
  StandaloneDirective,
  TriggerDef,
  VoidFn,
} from './types';
import { APP_ROOT_SELECTOR } from './core/constants';
import { fail, info, warn } from './core/diagnostics';
import { dispatchFrom } from './core/dispatch';
import { parseTriggers } from './core/parser';
import { ScopeRegistry } from './core/scope-registry';
import { isPlainObject } from './core/serializable';
import { installPlugins, type RousePlugin, resolvePlugins } from './plugin-api';
import type { PersistOptions } from './reactivity/persist';
import { StoreManager, type StoreOptions } from './store';

export interface RouseConfig {
  /** Element or selector where the app mounts. Defaults to `document.documentElement`. */
  root?: string | HTMLElement;
  /**
   * Prepended to relative URLs in `rz-fetch` and `app.fetch()`, and in the requests and
   * streams of the `sync` and `sse` plugins.
   */
  baseUrl?: string;
  /** Default headers applied to every request. Merged with per-request and directive-level headers; a `null` value removes the header. */
  headers?: Record<string, string | null>;
  /** The fetch `credentials` value for every request. Defaults to the browser's `'same-origin'`. */
  credentials?: RequestCredentials;
  /** Abort every request after this many milliseconds. A per-request `timeout` overrides it; `0` (the default) means no deadline. */
  timeout?: number;
  /** Default scope activation strategy. Overridden by `rz-wake`. */
  wake?: string;
  /**
   * Optional features to install in this app, such as `sync` from `rousejs/sync`.
   * Each is installed once, while the app is created. Throws if a plugin comes from a
   * different release than the core library.
   */
  plugins?: readonly RousePlugin[];
}

/**
 * The options passed to `rouse()`, with defaults filled in, read from `app.config`.
 * `root` is the resolved element, the same one `app.root` returns.
 */
interface ResolvedConfig {
  // Every `RouseConfig` key has a field here, so `app.config` lists every option.
  // Keep `root` even though `app.root` returns the same element.
  root: HTMLElement;
  baseUrl: string;
  headers: Record<string, string | null>;
  // Left unset rather than defaulted, so fetch applies its own
  credentials?: RequestCredentials;
  timeout: number;
  wake: string;
  /** The installed plugins, each listed once. */
  plugins: readonly RousePlugin[];
}

let bannerLogged = false;

/** One-time dev-build notice. Message and latch are both stripped from the min build. */
function logBuildBanner() {
  if (bannerLogged) {
    return;
  }
  bannerLogged = true;
  info(`v${__VERSION__} development build.`);
}

registerBoundDirectives(BOUND_DIRECTIVES);

/**
 * A Rouse application instance. Holds the root element, the stores, the
 * registered scopes, the network interceptors, and the `fetch` and `on` helpers.
 *
 * Creating an app touches the DOM only to claim the root; no directives are read
 * until `start()`, so stores and scopes can be registered in any order first.
 * A root hosts one app at a time, and the constructor throws rather than attach
 * a second.
 *
 * @example
 * const app = rouse({ root: '#app', baseUrl: '/api' });
 * app.store('cart', { items: [] });
 * app.scope('counter', counter);
 * app.start();
 */
export class RouseApp {
  public readonly root: HTMLElement;
  public readonly config: Readonly<ResolvedConfig>;
  public stores: StoreManager;
  /** @internal */
  public _registry: ScopeRegistry;
  /**
   * The `wake` config, parsed once. A scope without `rz-wake` waits on these.
   *
   * @internal
   */
  public readonly _wakeTriggers: TriggerDef[];
  public isReady: boolean;

  /**
   * Makes a network request using the app's configuration. Registered interceptors,
   * default headers, and credentials all apply, and a relative URL is resolved against
   * the configured `baseUrl`. Inside a scope, pass `signal: term` to abort the request
   * when the scope is destroyed.
   *
   * @example
   * const { data, error } = await app.fetch('/api/user');
   * const { data } = await app.fetch('/api/search', { signal: term });
   */
  public fetch: RouseFetch;

  /**
   * Adds an event listener that is auto-removed when the app is destroyed. Listens
   * on `app.root` unless an `EventTarget` is passed first. Inside a scope, pass the
   * host and `signal: term` to listen on the scope's element until it is destroyed.
   *
   * @returns A teardown closure that removes the listener early.
   *
   * @example
   * app.on('click', onClick, { debounce: 300 });
   * app.on(window, 'online', sync);
   * app.on({ interval: '30s' }, refresh);
   * app.on(host, 'input', search, { signal: term });
   */
  public on: BoundOn;

  /**
   * The standalone directives this app mounts, by slug, in mount order. Core's are
   * added at creation, and a plugin adds its own at install.
   *
   * @internal
   */
  public _standaloneDirectives = new Map<DirectiveSlug, StandaloneDirective>();

  /**
   * The trigger sources this app recognizes, by name. Core's are added at creation,
   * and a plugin adds its own at install.
   *
   * @internal
   */
  public _triggerSources = new Map<string, TriggerSource>(Object.entries(triggerSources));

  /** @internal */
  public _interceptors: {
    request: Set<RequestInterceptor>;
    response: Set<ResponseInterceptor>;
    error: Set<ErrorInterceptor>;
  };

  private _hasStarted = false;
  private _destroyed = false;
  private _abortController: AbortController;

  /**
   * Resolves the root, marks it with `data-rouse-app`, and wires the stores, scopes,
   * interceptors, and app-lifetime `AbortController`.
   *
   * @throws If the root cannot be found, or already has an app attached.
   */
  constructor(config: RouseConfig = {}) {
    if (__DEV__) {
      logBuildBanner();
    }

    // Before the root is claimed, so a mismatched plugin leaves it free for a retry
    const plugins = resolvePlugins(config.plugins);

    const rootEl =
      typeof config.root === 'string'
        ? (document.querySelector(config.root) as HTMLElement)
        : (config.root ?? document.documentElement);

    if (!rootEl) {
      fail('Root element not found.');
    }

    if (appAt(rootEl)) {
      fail('An app instance is already attached to this element.');
    }

    this.root = rootEl;

    this.config = {
      root: rootEl,
      baseUrl: config.baseUrl ?? '',
      headers: config.headers ?? {},
      credentials: config.credentials,
      timeout: config.timeout ?? 0,
      wake: config.wake?.trim() || 'ready',
      plugins,
    };

    // A malformed `wake` warns here, once, and falls back to `ready`
    const wake = parseTriggers(this.config.wake);
    this._wakeTriggers = wake.length ? wake : [{ event: 'ready', options: {} }];

    this._interceptors = {
      request: new Set(),
      response: new Set(),
      error: new Set(),
    };

    this.stores = new StoreManager(this);
    this._registry = new ScopeRegistry();
    STANDALONE_DIRECTIVES.forEach((directive) => this._addStandaloneDirective(directive));
    this.isReady = false;

    // An enclosing app that already scanned this markup still owns its bindings, so it
    // needs to release them first to prevent both apps writing the same elements. It
    // must happen before the root is marked: the release finds the parent's bindings
    // through `getApp`, which stops resolving them to the parent once it is.
    const parentRoot = rootEl.parentElement?.closest<HTMLElement>(APP_ROOT_SELECTOR);
    const parent = parentRoot ? appAt(parentRoot) : undefined;
    if (parent?._hasStarted) {
      flushMutations();
      releaseSubtree(rootEl, parent);
    }

    // Mark root so children can find parent app
    attachApp(this.root, this);

    // Bound so `app.fetch(url)` resolves to this instance
    this.fetch = this._fetch.bind(this);

    // App-lifetime signal, created here instead of in `start` so `app.on` can bind
    // before `app.start()` is called. Is aborted in `destroy`.
    this._abortController = new AbortController();

    // A lifecycle-safe listener bound to the app-lifetime signal, auto-removed on `destroy`
    this.on = (...args: any[]): VoidFn => {
      // A string or trigger descriptor as the first argument means the target was
      // omitted. Testing for a plain object rather than "not an EventTarget" keeps a
      // missed `querySelector`'s `null` reaching the TypeError below. One event per
      // call: a shared options bag can't serve several triggers' arguments.
      const implied = typeof args[0] === 'string' || isPlainObject(args[0]);
      const target = implied ? this.root : args[0];
      const event = implied ? args[0] : args[1];
      const callback = implied ? args[1] : args[2];
      const options: ListenerOptions = (implied ? args[2] : args[3]) ?? {};

      // A querySelector returns `null` if there's no match, and passing that through
      // throws a TypeError from inside Rouse that doesn't point back to this call.
      // Duck-typed, since `instanceof EventTarget` rejects another realm's `window`.
      if (typeof target?.addEventListener !== 'function') {
        fail(
          `app.on expected an EventTarget, but got ${target === null ? 'null' : typeof target}.`,
          TypeError,
        );
      }

      const signal = this._bindSignal(options.signal);

      return on(target, event, callback, { ...options, signal }, this);
    };

    // Last, so a plugin extends a fully wired app
    installPlugins(this, plugins);
  }

  /**
   * Registers a scope setup function by name. `data-rz-scope="counter"` resolves
   * against the names registered here.
   *
   * Elements are wired as they are scanned, and a name that is not registered before
   * `start()` is skipped with a warning rather than picked up once it arrives.
   *
   * @param name - Unique name. Referenced by `rz-scope`.
   * @param setup - The setup function.
   * @returns The app, so calls can be chained.
   * @throws If the setup is not a function.
   *
   * @example
   * app.scope('counter', ({ host, app }) => { ... });
   */
  scope<E extends Element = HTMLElement>(name: string, setup: ScopeSetup<E>): this {
    if (typeof setup !== 'function') {
      fail(`Scope '${name}' must be a setup function.`);
    }

    this._registry.register(name, setup);

    return this;
  }

  /**
   * Creates a reactive store and returns its data proxy.
   *
   * A store is one flat object. Data, getters, and methods live side by side.
   * Getters are cached as computeds bound to the proxy and must stay pure. Work
   * that needs cleanup belongs in a scope instead. Snapshots and incoming data touch
   * only plain, JSON-serializable data, never methods or getters.
   *
   * **Sync:** with the `sync` plugin installed, `config` also takes the store's
   * endpoint (`url`) and request options, and the store syncs with that endpoint as a
   * whole.
   *
   * **Persistence:** pass `persist` and `persistKey` to keep the data in the browser
   * across page loads.
   * - The saved copy is restored on creation.
   * - Every change saves the data fields as JSON.
   * - Saving stops on `stores.remove()` and `destroy()`. The saved copy stays in storage.
   *
   * @template T - Shape of the store's data, getters, and methods.
   * @param name - Unique name. Referenced as `@name` in directives.
   * @param data - Initial state, made reactive.
   * @param config - `persist` (`'local'` or `'session'`) with a `persistKey` used
   *   verbatim as the storage key. The `sync` plugin adds `url` and request options.
   * @returns The store's reactive proxy.
   * @throws If a store of this name already exists, or if `persist` is not `'local'` or
   *   `'session'` with a `persistKey`. With sync, also if `persist` is combined with
   *   `url`.
   *
   * @example
   * const cart = app.store('cart', {
   *   items: [],
   *   get total() {
   *     return this.items.reduce((sum, item) => sum + item.price, 0);
   *   },
   *   clear() {
   *     this.items = [];
   *   },
   * });
   *
   * cart.items.push(item);
   *
   * @example
   * app.store('prefs', { theme: 'light' }, { persist: 'local', persistKey: 'prefs' });
   *
   * @example
   * // With the sync plugin: rouse({ plugins: [sync] })
   * app.store('user', { name: '' }, { url: '/api/user' });
   */
  store<T extends object>(name: string, data: T, config?: StoreOptions & PersistOptions) {
    return this.stores._create<T>(name, data, config);
  }

  /**
   * Places an HTML string into the page, the programmatic counterpart to `rz-place`.
   * A selector is matched within the app root, including the root itself, and every
   * match receives the content.
   *
   * The position defaults to `innerHTML`. `outerHTML` replaces the target, `delete`
   * removes it (pass `''` as the content), and positions such as `beforeend` insert
   * next to or inside it. Each placement fires `rz:dom:place:before`, which can
   * cancel it or change the content, and then `rz:dom:place`. Those events reach
   * `app.on` listeners only when the target is inside the app root.
   *
   * @returns `true` if the content was placed into at least one element, `false` if nothing matched or every placement was canceled.
   *
   * @example
   * app.place('#feed', html, { position: 'beforeend' });
   * app.place(el, html);
   * app.place('#item-4', '', { position: 'delete' });
   */
  place(target: Element | string, content: string, options?: PlaceOptions): boolean {
    return placeContent(this, target, content, options);
  }

  /**
   * Registers a network interceptor. Interceptors run in FIFO order and are
   * `await`ed sequentially, so async interceptors block subsequent ones in
   * the same phase. Inside a scope, pass `signal: term` to remove it when the
   * scope is destroyed.
   *
   * A request interceptor can change the config in place or return the fields to
   * change, including `url` to send the request somewhere else. Leaving a field out
   * of the returned object doesn't remove it: set it to `undefined` instead.
   *
   * @returns A teardown closure that unregisters the interceptor.
   *
   * @example
   * const remove = app.interceptor('request', (config) => {
   *   config.headers = { ...config.headers, Authorization: `Bearer ${token}` };
   *   return config;
   * });
   * remove();
   *
   * app.interceptor('request', addScopeHeader, { signal: term });
   */
  interceptor(
    phase: 'request',
    fn: RequestInterceptor,
    options?: InterceptorOptions,
  ): VoidFn;
  interceptor(
    phase: 'response',
    fn: ResponseInterceptor,
    options?: InterceptorOptions,
  ): VoidFn;
  interceptor(phase: 'error', fn: ErrorInterceptor, options?: InterceptorOptions): VoidFn;
  interceptor(
    phase: InterceptorPhase,
    fn: any,
    { signal }: InterceptorOptions = {},
  ): VoidFn {
    const set = this._interceptors[phase];
    if (!set) {
      fail(
        `Invalid interceptor: '${phase}'. Expected 'request', 'response', or 'error'.`,
      );
    }
    if (typeof fn !== 'function') {
      fail(`Interceptor for '${phase}' must be a function.`);
    }

    if (!signal) {
      set.add(fn);
      return () => set.delete(fn);
    }

    // An aborted signal never fires `abort` again, so registering would leak
    if (signal.aborted) {
      return () => {};
    }

    // Interceptors are stored in a Set, so two scopes registering the same function
    // would share one entry, and the first teardown would remove it for both. A
    // wrapper per call gives each registration its own entry.
    const entry = (...args: any[]) => fn(...args);
    const remove = () => set.delete(entry);
    set.add(entry);
    signal.addEventListener('abort', remove, { once: true });

    return () => {
      signal.removeEventListener('abort', remove);
      remove();
    };
  }

  /**
   * Triggers a Rouse network request. `options.triggerEl` marks an originating
   * element; without one nothing is read from the DOM and the `rz:fetch:*`
   * events fire from the app root.
   */
  private async _fetch(url: string, options: FetchRequest = {}) {
    return runFetch(this, { ...options, url });
  }

  /**
   * Brings the app to life: reads the markup under `root`, creates stores, mounts
   * scopes, binds directives, and starts watching for elements added later.
   *
   * Fires `rz:app:start` before reading anything, and `rz:app:ready` on the next
   * animation frame, once the initial bindings have run and `isReady` is true.
   * Calling it a second time, or after `destroy()`, warns and does nothing.
   *
   * @example
   * document.addEventListener('DOMContentLoaded', () => app.start());
   */
  start() {
    if (this._destroyed) {
      if (__DEV__) {
        warn(
          `'start()' called on a destroyed app. Ignoring. Create a new instance instead.`,
        );
      }
      return;
    }
    if (this._hasStarted) {
      if (__DEV__) {
        warn(`'start()' called multiple times. Ignoring.`);
      }
      return;
    }

    this._hasStarted = true;

    dispatchFrom(this.root, this.root, 'rz:app:start', { app: this });

    // Observing first means DOM that a scope adds while mounting is still scanned
    observeApp(this);

    mountSubtree(this.root, this);

    requestAnimationFrame(() => {
      if (this._destroyed) {
        return;
      }
      this.isReady = true;
      dispatchFrom(this.root, this.root, 'rz:app:ready', { app: this });
    });
  }

  /**
   * Adds a standalone directive for this app to mount, and its slug to the selector
   * removed subtrees tear down through.
   *
   * @internal
   */
  _addStandaloneDirective(directive: StandaloneDirective): void {
    this._standaloneDirectives.set(directive.slug, directive);
    addStandaloneSlug(directive.slug);
  }

  /**
   * Returns a signal that aborts with the app, or with the caller's own signal if given.
   *
   * @internal
   */
  _bindSignal(signal?: AbortSignal): AbortSignal {
    const appSignal = this._abortController.signal;
    return signal ? AbortSignal.any([appSignal, signal]) : appSignal;
  }

  /**
   * Shuts the app down: stops watching the DOM, unmounts every scope, unbinds
   * every directive, then fires `rz:app:destroy` and aborts the app's signal.
   *
   * This is final. Aborting drops `app.on` listeners and any request still in
   * flight, and `start()` will not run again. Does nothing if the app never
   * started or is already gone.
   */
  destroy() {
    if (!this._hasStarted || this._destroyed) {
      return;
    }
    this._destroyed = true;

    unobserveApp(this);

    unmountSubtree(this.root);
    teardownGlobalBindings(this.root);
    this.stores._stopSaving();

    dispatchFrom(this.root, this.root, 'rz:app:destroy', { app: this });

    // Release after the destroy event so app.on('rz:app:destroy') fires and
    // getApp(e.target) still resolves.
    detachApp(this.root);
    this._abortController.abort();
  }
}

/**
 * Creates a Rouse app instance. The standard entry point; equivalent
 * to `new RouseApp(config)`.
 *
 * @param config - App-wide configuration, fixed once the app exists.
 * @returns A new app, ready for stores and scopes and waiting on `start()`.
 *
 * @example
 * const app = rouse({ root: '#app' });
 * app.scope('counter', counter);
 * app.start();
 */
export function rouse(config: RouseConfig = {}): RouseApp {
  return new RouseApp(config);
}
