import { warn } from './diagnostics';
import { isOwnDataProp, isPlainObject, toJSONValue } from './serializable';

/**
 * Deep-clones `input` as JSON serialization encodes it. Honors `toJSON()` and strips
 * functions, `undefined`, and accessors. Any other non-plain object becomes `{}`, with
 * a dev warning. Produces snapshots safe to JSON-serialize, diff, or use as restore
 * targets.
 */
export function clone<T>(input: T, seen = new WeakMap(), path = 'root'): T {
  const obj = toJSONValue(input) as T;
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  if (seen.has(obj as any)) {
    return seen.get(obj as any);
  }

  // Arrays: JSON converts functions/undefined to null to preserve indexes.
  // This also normalizes sparse arrays (holes become null).
  if (Array.isArray(obj)) {
    const arr = [] as any[];
    seen.set(obj as any, arr);
    for (let i = 0; i < obj.length; i++) {
      const val = obj[i];
      arr[i] =
        typeof val === 'function' || val === undefined
          ? null
          : clone(val, seen, __DEV__ ? `${path}[${i}]` : '');
    }
    return arr as unknown as T;
  }

  // Catch complex objects before network sync
  if (!isPlainObject(obj)) {
    if (__DEV__) {
      warn(
        `Non-serializable value at '${path}'. Use plain objects, arrays, or primitives.`,
      );
    }
    return {} as T;
  }

  // Objects: JSON completely strips properties that are functions or undefined.
  const result = {} as Record<string, any>;
  seen.set(obj as any, result);

  for (const key in obj) {
    if (!isOwnDataProp(obj as object, key)) {
      continue;
    }
    const val = (obj as Record<string, any>)[key];
    if (val !== undefined) {
      result[key] = clone(val, seen, __DEV__ ? `${path}.${key}` : '');
    }
  }

  return result as T;
}

/**
 * Returns `true` when `obj` has `key` as an accessor or method rather than plain data.
 */
export function hasAccessor(obj: object, key: string): boolean {
  return !isOwnDataProp(obj, key) && !!Object.getOwnPropertyDescriptor(obj, key);
}

/**
 * Writes `source` into `target`. `replace` deletes keys absent from the source;
 * `merge` applies JSON Merge Patch (RFC 7396) semantics, where absent keys are
 * left alone and a `null` removes the key it names.
 *
 * `shape`, for a merge only, is a live object that `target` mirrors. A key that's
 * an accessor there is skipped here too, so a plain copy of a store, such as its
 * baseline, takes a patch exactly as the store does.
 */
export function patchState(
  target: Record<string, any>,
  source: Record<string, any>,
  action: 'replace' | 'merge' = 'replace',
  shape?: Record<string, any>,
) {
  // Replace
  if (action === 'replace') {
    for (const key of Object.keys(target)) {
      if (!isOwnDataProp(target, key)) {
        continue;
      }
      if (!Object.hasOwn(source, key)) {
        delete target[key];
      }
    }
    // Write source values into target, skipping keys where target has an accessor.
    // Writing through a getter-only accessor would throw, and even when a setter
    // exists, this loop is for data-property merge.
    for (const key of Object.keys(source)) {
      if (hasAccessor(target, key)) {
        continue;
      }
      target[key] = source[key];
    }
    return;
  }

  // Merge
  for (const sourceKey of Object.keys(source)) {
    if (!isOwnDataProp(source, sourceKey)) {
      continue;
    }

    const sourceVal = (source as Record<string, any>)[sourceKey];
    if (sourceVal === undefined) {
      continue;
    }

    // Skip derived state, on the target or on the live object it mirrors
    if (
      hasAccessor(target, sourceKey) ||
      (isPlainObject(shape) && hasAccessor(shape, sourceKey))
    ) {
      continue;
    }

    // RFC 7396: null values indicate removal
    if (sourceVal === null) {
      delete target[sourceKey];
      continue;
    }

    const targetVal = target[sourceKey];
    const nestedShape = isPlainObject(shape) ? shape[sourceKey] : undefined;

    // An object patched over a non-object target seeds `{}` and merges into it
    // rather than being assigned wholesale, which is what drops the nulls nested
    // inside it. Re-read after seeding: the proxy wraps what was just written.
    if (isPlainObject(sourceVal)) {
      if (isPlainObject(targetVal)) {
        patchState(targetVal, sourceVal, 'merge', nestedShape);
      } else {
        target[sourceKey] = {};
        patchState(target[sourceKey], sourceVal, 'merge', nestedShape);
      }
    } else {
      target[sourceKey] = sourceVal;
    }
  }
}
